def _bounds(day):
    first_year = day.year if day.month >= 9 else day.year - 1
    return f"{first_year}-{first_year + 1}", date(first_year, 9, 1), date(first_year + 1, 8, 31)


def attach_school_years(apps, schema_editor):
    SchoolYear = apps.get_model("library", "SchoolYear")
    SchoolClass = apps.get_model("library", "SchoolClass")
    Loan = apps.get_model("library", "Loan")

    def year_for(day):
        name, start, end = _bounds(day)
        year, _ = SchoolYear.objects.get_or_create(name=name, defaults={"start_date": start, "end_date": end})
        return year

    current = year_for(timezone.localdate())
    SchoolYear.objects.filter(pk=current.pk).update(is_current=True)
    SchoolClass.objects.filter(school_year__isnull=True).update(school_year=current)
    for checkout_date in Loan.objects.filter(school_year__isnull=True).values_list("checkout_date", flat=True).distinct():
        Loan.objects.filter(school_year__isnull=True, checkout_date=checkout_date).update(school_year=year_for(checkout_date))


